(async()=>{try{const response=await fetch('/assets/portfolio.json');if(!response.ok)return;const data=await response.json();const container=document.getElementById('portfolio-projects');const projects=Array.isArray(data.projects)?data.projects:[];let count=0;for(const project of projects){if(!project.title||!project.image||!project.url||!project.url.startsWith('/portfolio/')||!project.image.startsWith('/assets/'))continue;const card=document.createElement('a');card.className='project-card';card.href=project.url;const img=document.createElement('img');img.src=project.image;img.alt=project.imageAlt||project.title;img.loading='lazy';const label=document.createElement('p');label.className='eyebrow';label.textContent=project.category||'Proyecto';const title=document.createElement('h2');title.textContent=project.title;card.append(img,label,title);container.append(card);count++}if(count)document.getElementById('portfolio-empty').hidden=true}catch{}})();